{"filePath":"c:\PowerShellGUI\temp\fix-fileroles-dup.ps1","content":"[CmdletBinding()] param([switch]$WhatIf)

$paths = @()
$paths += Get-ChildItem C:\PowerShellGUI\modules -Filter '*.psm1' -File
$paths += Get-ChildItem C:\PowerShellGUI\scripts -Recurse -Filter '*.ps1' -File |
    Where-Object {
        $_.FullName -notlike '*\.history*' -and
        $_.FullName -notlike '*~REPORTS*' -and
        $_.FullName -notlike '*\QUICK-APP\*' -and
        $_.FullName -notlike '*\windguits\*' -and
        $_.FullName -notlike '*\scripts\scripts\*'
    }

foreach ($p in $paths) {
    $bytes = [System.IO.File]::ReadAllBytes($p.FullName)
    if ($bytes.Length -lt 10) { continue }
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    # Look for pattern: line1=# VersionTag, line2=# FileRole, line3 starts with BOM(\uFEFF) + # VersionTag
    $pattern = "^(# VersionTag:[^\r\n]*\r?\n# FileRole:[^\r\n]*\r?\n)\uFEFF(# VersionTag:)"
    if ([regex]::IsMatch($text, $pattern)) {
        # Strip the duplicate prepended pair AND the embedded BOM
        $newText = [regex]::Replace($text, $pattern, '$2', 'Singleline')
        if ($WhatIf) { Write-Host "WOULD FIX $($p.FullName)"; continue }
        # Re-emit with BOM at start (since original VersionTag line had BOM)
        $enc = New-Object System.Text.UTF8Encoding($true)
        [System.IO.File]::WriteAllText($p.FullName, $newText, $enc)
        Write-Host "FIXED $($p.FullName)"
    }
}
Write-Host "DONE"
"}

