function Add-CheckResult {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Name,

        [Parameter(Mandatory)]
        [bool]$Pass,

        [Parameter()]
        [string]$Detail = ''
    )

    $entry = [pscustomobject]@{
        Name   = $Name
        Pass   = $Pass
        Detail = $Detail
    }
    $script:Checks += $entry

    if ($Pass) {
        Write-Host ("[PASS] {0}" -f $Name) -ForegroundColor Green
    } else {
        $suffix = if ([string]::IsNullOrWhiteSpace($Detail)) { '' } else { ': ' + $Detail }
        Write-Host ("[FAIL] {0}{1}" -f $Name, $suffix) -ForegroundColor Red
    }
}

function Get-FunctionBody {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Source,

        [Parameter(Mandatory)]
        [string]$FunctionName
    )

    $pattern = 'function\s+' + [regex]::Escape($FunctionName) + '\s*\([^\)]*\)\s*\{'
    $match = [regex]::Match($Source, $pattern)
    if (-not $match.Success) { return $null }

    $depth = 1
    $index = $match.Index + $match.Length
    while ($index -lt $Source.Length -and $depth -gt 0) {
        $char = $Source[$index]
        if ($char -eq '{') {
            $depth++
        } elseif ($char -eq '}') {
            $depth--
        }
        $index++
    }

    if ($depth -ne 0) { return $null }
    return $Source.Substring($match.Index, $index - $match.Index)
}

function Test-FunctionPatterns {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Source,

        [Parameter(Mandatory)]
        [string]$FunctionName,

        [Parameter(Mandatory)]
        [string[]]$RequiredPatterns
    )

    $body = Get-FunctionBody -Source $Source -FunctionName $FunctionName
    Add-CheckResult -Name ("Function exists: {0}" -f $FunctionName) -Pass ($null -ne $body) -Detail ("Missing function: {0}" -f $FunctionName)
    if ($null -eq $body) { return }

    foreach ($pattern in @($RequiredPatterns)) {
        $present = [regex]::IsMatch($body, $pattern, [System.Text.RegularExpressions.RegexOptions]::Singleline)
        Add-CheckResult -Name ("{0} contains pattern: {1}" -f $FunctionName, $pattern) -Pass $present -Detail 'Expected transition logic was not found.'
    }
}

