+function _so_inferTaskTrayStatus(payload){
+  if (!payload) return { state: 'pending', text: 'tray: PENDING', detail: 'Awaiting engine payload for tray monitor state' };
+  var asText = '';
+  try { asText = JSON.stringify(payload).toLowerCase(); } catch (e) { asText = ''; }
+  if (!asText) return { state: 'pending', text: 'tray: PENDING', detail: 'Engine payload could not be parsed for tray monitor state' };
+  var hasTrayMarker = asText.indexOf('tray') >= 0 || asText.indexOf('notifyicon') >= 0 || asText.indexOf('tasktray') >= 0;
+  if (!hasTrayMarker) return { state: 'pending', text: 'tray: UNKNOWN', detail: 'No tray monitor marker found in engine payload' };
+  if (asText.indexOf('trayrunning":true') >= 0 || asText.indexOf('tasktray":true') >= 0 || asText.indexOf('notifyicon":true') >= 0 || asText.indexOf('tray":"online') >= 0 || asText.indexOf('tray":"running') >= 0) {
+    return { state: 'online', text: 'tray: ONLINE', detail: 'Task tray monitor markers reported as online/running in engine payload' };
+  }
+  if (asText.indexOf('trayrunning":false') >= 0 || asText.indexOf('tasktray":false') >= 0 || asText.indexOf('notifyicon":false') >= 0 || asText.indexOf('tray":"offline') >= 0 || asText.indexOf('tray":"stopped') >= 0) {
+    return { state: 'offline', text: 'tray: OFFLINE', detail: 'Task tray monitor markers reported as offline/stopped in engine payload' };
+  }
+  return { state: 'pending', text: 'tray: PENDING', detail: 'Tray markers present but no explicit online/offline state reported' };
+}
