+  el.setAttribute('tabindex', '0');
+  el.setAttribute('role', 'link');
+  el.addEventListener('click', function(ev) {
+    var openFolder = !!(ev && ev.ctrlKey && ev.altKey);
+    var target = openFolder ? _so_resolveFolderHref(refValue) : _so_resolveRefHref(refValue);
+    if (!target) return;
+    try { window.open(target, '_blank'); } catch (e) { window.location.href = target; }
+  });
+  el.addEventListener('keydown', function(ev) {
+    if (!ev) return;
+    if (ev.key === 'Enter' || ev.key === ' ') {
+      ev.preventDefault();
+      el.click();
+    }
+  });
+}
+
+function _so_refreshFooterRefTooltips() {
+  var policy = _so_getValidationPolicy();
+  var refs = document.querySelectorAll('footer .ft-ref');
+  for (var i = 0; i < refs.length; i++) {
+    var el = refs[i];
+    var txt = String(el.textContent || '').trim();
+    if (!txt) continue;
+    var refValue = txt;
+    if (el.id === 'ftLiveSummary') refValue = 'http://127.0.0.1:8042/api/engine/status';
+    else if (el.id === 'ftLiveWebCluster8099') refValue = 'http://127.0.0.1:8099/health';
+
+    var isLiveOnly = _so_isLiveOnlyRef(txt) || _so_isLiveOnlyRef(refValue);
+    var isPath = _so_isPathLikeRef(refValue);
+    var fileHref = _so_resolveRefHref(refValue);
+    var folderHref = _so_resolveFolderHref(refValue);
+    var title = [
+      txt,
+      'Mode=' + ((_soDataMode && _soDataMode.name) ? _soDataMode.name : DATASOURCE_MODES.PENDING),
+      'ignoreLiveChecks=' + policy.ignoreLiveChecks
+    ];
+    if (isLiveOnly) {
+      title.push('LIVE source: ' + (policy.ignoreLiveChecks ? 'ignored by current validation policy' : 'checked when online'));
+      el.classList.add('ft-live-only');
+    } else {
+      el.classList.remove('ft-live-only');
+    }
+
+    if (fileHref) title.push('Open=' + _so_toAbsoluteHref(fileHref));
+    if (folderHref) title.push('Folder=' + _so_toAbsoluteHref(folderHref));
+    if (isPath || /^https?:\/\//i.test(refValue)) {
+      title.push('Click: open ref');
+      title.push('Ctrl+Alt+Click: open folder/location');
+      el.classList.add('ft-clickable');
+      _so_attachFooterRefClick(el, refValue);
+    } else {
+      el.classList.remove('ft-clickable');
+    }
+    el.setAttribute('title', title.join('\n'));
+  }
+}

