+var FEATURE_CHECKPOINT_STORAGE_KEY = 'pwshgui_feature_checkpoints_v1';
+var FEATURE_REVIEW_STATUS_OPTIONS = [
+  'PENDING_REVIEW', 'VALIDATED', 'APPROVED_COMPLETED', 'DRAFT', 'PROTOTYPE', 'TESTING',
+  'HAS_FAULTS_BUGS', 'BROKEN', 'BLOCKED', 'ON_HOLD', 'DEFERRED', 'BACKLOGGED',
+  'FORKED', 'MERGED', 'CANCELLED', 'COMBINED'
+];
+var FEATURE_AUTOCHECKPOINT_TITLES = [
+  'Prototype creation',
+  'Runtime testing',
+  'Integration testing',
+  'Report testing',
+  'Pipeline testing',
+  'Smoke testing',
+  'README contents',
+  'Manifest entries',
