+  'Fast Feature Build Pack': [
+    'Prototype creation',
+    'Integration testing',
+    'Runtime testing',
+    'README contents',
+    'Manifest entries',
+    'Versioning',
+    'Metadata tags',
+    'Security'
+  ],
+  'Feature Testing Method Outcomes': [
+    'Approved + completed validation',
+    'Deferred validation outcome',
+    'Blocked validation outcome',
+    'On hold validation outcome',
+    'Merged validation outcome',
+    'Backlogged validation outcome',
+    'Forked validation outcome'
+  ],
+  'Refactor Regression Re-Issue Pack': [
+    'Runtime regression retest',
+    'Integration regression retest',
+    'Pipeline regression retest',
+    'Smoke regression retest',
+    'README and manifest regression review',
+    'Version and metadata regression review'
+  ]
+};
+var _featureCheckpointState = _featureLoadCheckpointState();
+
+function _featureNowIso() {
+  return (new Date()).toISOString();
+}
+
+function _featureClone(value) {
+  return JSON.parse(JSON.stringify(value));
+}
+
+function _featureLoadCheckpointState() {
+  var fallback = { version: 1, features: {}, templates: {} };
+  try {
+    var raw = localStorage.getItem(FEATURE_CHECKPOINT_STORAGE_KEY);
+    if (!raw) return fallback;
+    var parsed = JSON.parse(raw);
+    if (!parsed || typeof parsed !== 'object') return fallback;
+    parsed.features = parsed.features || {};
+    parsed.templates = parsed.templates || {};
+    parsed.version = parsed.version || 1;
+    return parsed;
+  } catch (e) {
+    return fallback;
+  }
+}
+
+function _featureSaveCheckpointState() {
+  try {
+    localStorage.setItem(FEATURE_CHECKPOINT_STORAGE_KEY, JSON.stringify(_featureCheckpointState));
+  } catch (e) {
+    if (typeof console !== 'undefined') console.warn('Feature checkpoint state save failed:', e.message);
+  }
+}
+
+function _featureBuildKey(item) {
+  return String(item.todo_id || item.id || item.title || 'feature') + '|' + String(item.created_at || item.created || 'na');
+}
+
+function _featureFindItemByKey(featureKey) {
+  for (var i = 0; i < allItems.length; i++) {
+    var item = allItems[i];
+    if (getItemType(item) !== 'feature') continue;
+    if (_featureBuildKey(item) === featureKey) return item;
+  }
+  return null;
+}
+
+function _featureResolveKey(encodedFeatureKey) {
+  try { return decodeURIComponent(String(encodedFeatureKey || '')); } catch (e) { return String(encodedFeatureKey || ''); }
+}
+
+function _featureResolveCheckpointId(encodedCheckpointId) {
+  try { return decodeURIComponent(String(encodedCheckpointId || '')); } catch (e) { return String(encodedCheckpointId || ''); }
+}
+
+function _featureGetRecordForKey(featureKey, createIfMissing) {
+  if (!_featureCheckpointState.features[featureKey] && createIfMissing) {
+    _featureCheckpointState.features[featureKey] = {
+      statusOverride: '',
+      checkpoints: [],
+      updatedAt: _featureNowIso()
+    };
+  }
+  return _featureCheckpointState.features[featureKey] || null;
