+    </span>
   </div>
@@
 function _scanToolsEnhanceTable() {
   var table = document.getElementById('sc-table') || document.querySelector('#scan-tools table');
   if (!table || table.getAttribute('data-enhanced') === '1') return;
@@

   table.setAttribute('data-enhanced', '1');
 }
+
+function _scanToolsGetRunTypeFilterValue() {
+  var sel = document.getElementById('scRunTypeFilter');
+  return sel ? String(sel.value || 'ALL') : 'ALL';
+}
+
+function _scanToolsApplyRunTypeFilter(filterValue) {
+  var mode = String(filterValue || _scanToolsGetRunTypeFilterValue() || 'ALL');
+  var sel = document.getElementById('scRunTypeFilter');
+  if (sel && sel.value !== mode) sel.value = mode;
+
+  var table = document.getElementById('sc-table') || document.querySelector('#scan-tools table');
+  if (!table) return;
+
+  var rows = table.querySelectorAll('tr[data-scan-script]');
+  for (var i = 0; i < rows.length; i++) {
+    var runCell = rows[i].querySelector('.sc-run-type');
+    var runType = runCell ? String(runCell.textContent || '--').trim() : '--';
+    var show = (mode === 'ALL') || (runType === mode) || runType === '--';
+    rows[i].style.display = show ? '' : 'none';
+  }
+}
+
+function _scanToolsRefreshMetadata(btn) {
+  var button = btn || document.getElementById('scRefreshMetaBtn');
+  if (button && button.disabled) return;
+
+  if (button) {
+    button.disabled = true;
+    button.textContent = 'Refreshing...';
+  }
+
+  window._scanToolsManifest = null;
+  window._scanToolsManifestByScript = {};
+  window._scanToolsDependencyCallers = {};
+  window._scanToolsDependencyMeta = { loaded: false, source: '--', generated: '--' };
+  window._scanToolsInitStarted = false;
+
+  var pending = 2;
+  function done() {
+    pending--;
+    if (pending > 0) return;
+    _scanToolsRefreshRows();
+    renderScanToolsValidation();
+    if (button) {
+      button.disabled = false;
+      button.textContent = '\u21BB Refresh Metadata';
+    }
+  }
+
+  _scanToolsRefreshRows();
+  _scanToolsLoadManifest(function() { _scanToolsRefreshRows(); done(); });
+  _scanToolsLoadDependencyLinks(function() { _scanToolsRefreshRows(); done(); });
+}

 function _scanToolsRefreshRows() {
   var table = document.getElementById('sc-table') || document.querySelector('#scan-tools table');
   if (!table) return;
