{"command":"Set-Location 'c:\PowerShellGUI';
$raw = Get-Content -LiteralPath '.\todo\_bundle.js' -Raw -Encoding UTF8;
$start = $raw.IndexOf('var _todoBundle');
$arrStart = $raw.IndexOf('[', $start);
$arrEnd = $raw.LastIndexOf('];');
$json = $raw.Substring($arrStart, ($arrEnd - $arrStart) + 1);
$items = @($json | ConvertFrom-Json);
function Normalize-Status([object]$s){
  $st = if($null -eq $s -or [string]::IsNullOrWhiteSpace([string]$s)){'OPEN'}else{[string]$s};
  $st = $st.ToUpperInvariant();
  $st = [regex]::Replace($st,'[\s/\\-]+','_');
  $st = [regex]::Replace($st,'__+','_');
  switch($st){
    'INPROGRESS' {'IN_PROGRESS'}
    'PENDINGAPPROVAL' {'PENDING_APPROVAL'}
    'AWAITING_APPROVAL' {'PENDING_APPROVAL'}
    'APPROVAL_PENDING' {'PENDING_APPROVAL'}
    'APPROVED' {'APPROVED_COMPLETED'}
    'APPROVED_COMPLETE' {'APPROVED_COMPLETED'}
    'APPROVED_DONE' {'APPROVED_COMPLETED'}
    'ONHOLD' {'ON_HOLD'}
    'REJECTED' {'DENIED'}
    'MERGED_TO_MAIN' {'MERGED'}
    'MERGED_MAIN' {'MERGED'}
    'MERGEDPR' {'MERGED'}
    'BUNDLE' {'BUNDLED'}
    'BUNDLED_INTO_RELEASE' {'BUNDLED'}
    'BUNDLEDTORELEASE' {'BUNDLED'}
    'BACKLOG' {'BACKLOGGED'}
    'BACKLOG_ITEM' {'BACKLOGGED'}
    'FORK' {'FORKED'}
    'FORK_REQUIRED' {'FORKED'}
    'FAULTS_BUGS' {'HAS_FAULTS_BUGS'}
    'HAS_FAULTS' {'HAS_FAULTS_BUGS'}
    'BUGGY' {'HAS_FAULTS_BUGS'}
    'DEFER' {'DEFERRED'}
    'DEFERRED_ITEM' {'DEFERRED'}
    default {$st}
  }
}
function Normalize-Type([object]$t){
  $tv = if($null -eq $t){''}else{[string]$t};
  if([string]::IsNullOrWhiteSpace($tv)){ return 'todo' }
  $x = $tv.ToLowerInvariant();
  if($x -eq 'bugs2fix'){ return 'bug' }
  if($x -eq 'items2add' -or $x -eq 'todo'){ return 'todo' }
  if($x -eq 'featurerequest'){ return 'feature' }
  return $x
}
$rows = foreach($it in $items){
  [pscustomobject]@{
    Id = if($it.PSObject.Properties.Name -contains 'id'){[string]$it.id}else{''}
    Title = if($it.PSObject.Properties.Name -contains 'title'){[string]$it.title}else{''}
    Type = Normalize-Type (if($it.PSObject.Properties.Name -contains 'type'){$it.type}else{$null})
    Status = Normalize-Status (if($it.PSObject.Properties.Name -contains 'status'){$it.status}else{$null})
    Priority = if($it.PSObject.Properties.Name -contains 'priority'){[string]$it.priority}else{''}
    Severity = if($it.PSObject.Properties.Name -contains 'severity'){[string]$it.severity}else{''}
    SourceFile = if($it.PSObject.Properties.Name -contains 'sourceFile'){[string]$it.sourceFile}else{''}
  }
}
'--- TOTALS BY TYPE ---';
$rows | Group-Object Type | Sort-Object Name | Select-Object Name,Count | Format-Table -Auto;
'--- TOTALS BY TYPE+STATUS ---';
$rows | Group-Object Type,Status | Sort-Object Name | Select-Object Name,Count | Format-Table -Auto;
'--- ANY STATUS COUNT EXACTLY 48 ---';
