$summary = [pscustomobject]@{
  OriginalItemCount = @($doc.Items).Count
  DedupItemCount = @($dedup).Count
  OriginalHours = $totOriginal
  DedupHours = $totDedup
  SavedHours = $totSaved
  OriginalDays8h = [math]::Round($totOriginal / 8, 2)
  DedupDays8h = [math]::Round($totDedup / 8, 2)
  SavedDays8h = [math]::Round($totSaved / 8, 2)
};
'--- DEDUPE SUMMARY ---';
$summary | Format-List;
'--- DEDUPE GROUPS ---';
$dedup | Select-Object Count,EtaHoursEach,DedupHours,OriginalHours,SavedHours,ExampleId,Title | Format-Table -Auto","explanation":"Group the 48 open items by duplicate title to produce de-duplicated ETA totals and savings.","goal":"Generate deduped ETA summary","mode":"sync","timeout":120000}
